import{t as e}from"./jsx-runtime-lw2jiZar.js";import{C as t,D as n,M as r,N as i,O as a,P as o,b as s,k as c,l,n as u,o as d,p as f,t as p,v as m,x as h}from"./shared-C5BCElVa.js";import{t as g}from"./cloud-BBv7Rv1J.js";import{t as _}from"./git-branch--KUP4I0u.js";import{t as v}from"./CodeEditor-BZlrvoTL.js";var y=e(),b=`Глава 4 · Блок 13 · FastAPI как цельное приложение`;function x({module:e}){return(0,y.jsxs)(i,{children:[(0,y.jsx)(r,{variant:`project`,chip:e??b,title:`Зависимости и тесты`,intro:`Сгруппируем параметры существующего GET /tasks и передадим их вместе с Planner в provider только чтения: он вызывает выборку и не меняет задачи. Затем заменим provider в API-проверке, чтобы работать с отдельным JSON-файлом.`,tags:[{icon:(0,y.jsx)(_,{size:14}),label:`небольшой граф`},{icon:(0,y.jsx)(g,{size:14}),label:`изолированная проверка`}]}),(0,y.jsxs)(o,{number:`00`,title:`От готовой выборки к её входам`,children:[(0,y.jsx)(a,{children:`GET /tasks уже умеет отбирать задачи по статусу, менять порядок и ограничивать число результатов. Саму выборку выполняет существующий PlannerService. Теперь разберём, как отдельно подготовить входы запроса и не переписать прикладную операцию.`}),(0,y.jsx)(c,{variant:`connected`,items:[{title:`Точка старта`,description:`У запроса есть знакомые is_done, sort_desc и limit; select_tasks применяет их к задачам.`},{title:`Новый вопрос`,description:`Как передать подготовленные параметры и тот же Planner одному provider, а в проверке подменить только нужную зависимость?`},{title:`Результат`,description:`GET сохраняет свой HTTP-контракт, а отдельный JSON-сервис можно подключить на время API-проверки.`}]}),(0,y.jsx)(`p`,{children:`Сначала восстановим реальный путь данных, затем введём контейнер параметров и короткий граф. Мы также разберём, где заканчивается область одного запроса и как вернуть приложение в прежнее состояние после временной подмены.`})]}),(0,y.jsxs)(o,{number:`01`,title:`Сохраняем знакомую операцию`,children:[(0,y.jsx)(a,{children:`До рефакторинга обработчик получает query-параметры и передаёт их сервису. Query string остаётся частью HTTP-запроса; фильтрация, сортировка и limit остаются поведением PlannerService.`}),(0,y.jsx)(v,{caption:`схематичный фрагмент существующего GET`,code:[`tasks = request.app.state.planner.select_tasks(`,`    is_done=is_done,`,`    sort_desc=sort_desc,`,`    limit=limit,`,`)`,`return [_task_read_data(task) for task in tasks]`].join(`
`)}),(0,y.jsx)(`p`,{children:`Здесь нет двух фильтров. Endpoint получает данные из FastAPI, вызывает один метод сервиса, а затем превращает каждую внутреннюю Task в прежнюю публичную форму. Новая зависимость изменит место подготовки аргументов, но не владельца операции. Поэтому POST, PUT, PATCH и DELETE продолжат обращаться к тому же Planner обычным путём.`}),(0,y.jsx)(`p`,{children:`Параметры похожи на заполненную маршрутную карточку: отметка статуса, направление порядка и предел списка. Карточка помогает передать условия вместе, но не сама выбирает и не меняет задачи. В нашем проекте такую карточку назовём SelectionParams.`}),(0,y.jsx)(f,{prompt:`Сопоставим HTTP-вход, значение и владельца операции.`,leftTitle:`Что передали`,rightTitle:`Как читаем`,pairs:[{left:`is_done отсутствует`,right:`Не фильтруем по статусу`},{left:`is_done=False`,right:`Оставляем только открытые задачи`},{left:`limit=10`,right:`Сохраняем прежний предел по умолчанию`},{left:`select_tasks`,right:`Сервис применяет условия к задачам`}],explanation:`None и False имеют разный смысл, а сама фильтрация остаётся внутри select_tasks.`})]}),(0,y.jsxs)(o,{number:`02`,title:`Контейнер группирует, но не становится Task`,children:[(0,y.jsx)(a,{children:`SelectionParams собирает только три значения, которые уже описывают GET-выборку. Он не представляет одну задачу, не приходит в JSON-body и не создаёт новое состояние Planner.`}),(0,y.jsx)(`p`,{children:`Мы уже встречали dataclass как способ хранить связанные значения одного объекта. Здесь это обычный контейнер параметров. Его поля повторяют прежние имена и типы: is_done может быть bool или None, sort_desc остаётся bool, limit остаётся int. Контейнер не должен добавлять offset, поиск или ещё один фильтр, которого не было в публичном API.`}),(0,y.jsx)(v,{caption:`независимый пример контейнера`,code:[`from dataclasses import dataclass`,``,`@dataclass`,`class DigestFilter:`,`    category: str`,`    max_items: int`].join(`
`)}),(0,y.jsx)(`p`,{children:`В независимом DigestFilter поля category и max_items описывают выборку писем, но сам контейнер не читает почту. В Planner мы передаём одну карточку подготовки вместо трёх разрозненных значений, сохраняя прежнюю семантику. Если is_done равен None, фильтра по статусу нет. Если он равен False, остаются только открытые задачи. Значение sort_desc=False также явно означает прямой порядок. Контейнер не должен превратить False или None в отсутствие поля.`}),(0,y.jsx)(`p`,{children:`FastAPI разбирает query-строки в bool и int, применяет default limit=10 и сохраняет прежний диапазон от 1 до 50. Значения вне него и неверный тип дают 422 до вызова select_tasks. Dataclass хранит готовые поля, но не выполняет HTTP-валидацию.`}),(0,y.jsx)(`p`,{children:`Представим форму поиска свободных комнат. В ней можно собрать дату, требование к доступности и предел результатов; сама форма не является комнатой, а список комнат выбирает каталог. Так же SelectionParams описывает запрос, а PlannerService остаётся владельцем поиска задач.`}),(0,y.jsx)(m,{code:[`def make_options(day, limit):`,`    return {"day": day, "limit": limit}`,``,`options = make_options("Sat", 3)`,`print(options["limit"])`].join(`
`),steps:[{line:0,note:`Функция получает два входа. Мы пока не меняем исходный список событий.`,vars:{day:`"Sat"`,limit:`3`}},{line:1,note:`Возвращается контейнер значений. Его можно передать следующей функции как один результат.`,vars:{options:`{'day': 'Sat', 'limit': 3}`}},{line:3,note:`Вызов сохраняет возвращённый объект в options.`,vars:{options:`{'day': 'Sat', 'limit': 3}`}},{line:4,note:`Следующая строка читает поле контейнера. Сам контейнер ничего не выбирает и не изменяет.`,vars:{limit:`3`,output:`3`}}]}),(0,y.jsx)(`p`,{children:`Это независимый пример: функция собирает результат, а вызывающий код решает, как его применить. В API передачу выполнит FastAPI.`})]}),(0,y.jsxs)(o,{number:`03`,title:`Provider возвращает значение для другого узла`,children:[(0,y.jsx)(a,{children:`Dependency, или зависимость FastAPI, нужна обработчику как готовое значение. Provider - вызываемая функция, которая это значение подготавливает или получает. Depends объявляет FastAPI, какую функцию связать с параметром; сам аргумент Depends(get_selection) не вызывает provider вручную.`}),(0,y.jsx)(`p`,{children:`Перед чтением графа восстановим синтаксис на независимом примере. Annotated позволяет оставить тип и рядом добавить метаданные FastAPI. В параметре отчёта такая запись говорит: тип результата известен, а получить его нужно через get_filters. PlannerDep устроен по тому же принципу: это короткое имя для зависимости, которая возвращает уже созданный Planner.`}),(0,y.jsx)(v,{caption:`независимый пример, фрагмент сигнатуры`,code:[`def read_schedule(`,`    filters: Annotated[ScheduleFilters, Depends(get_filters)],`,`    calendar: CalendarDep,`,`):`,`    return calendar.find(filters)`].join(`
`)}),(0,y.jsx)(`p`,{children:`В строке filters сначала указан тип результата, затем Depends с исходной функцией. FastAPI читает эту метаинформацию при разборе запроса и получает результат get_filters для аргумента filters. Это не вызов get_filters во время импорта модуля и не значение, которое клиент присылает в body. В нашем GET три query-поля будут входами get_selection, а возвращённый SelectionParams станет одним из двух входов общего provider. PlannerDep обозначает второй готовый результат и сохраняет имя функции, которую можно заменить в тесте.`}),(0,y.jsx)(`p`,{children:`FastAPI видит объявленные зависимости и перед вызовом обработчика получает их результаты. В нашем проекте get_selection создаёт SelectionParams из прежних query-полей, а get_planner возвращает тот же сервис, который приложение уже хранит. Верхний read-only provider get_selected_tasks получает оба результата, вызывает знакомый select_tasks и возвращает список Task. Обработчик затем строит прежний HTTP-ответ.`}),(0,y.jsx)(`p`,{children:`Сравним это с рабочим столом, где одна заявка требует двух справок. Один сотрудник готовит фильтр, другой находит нужный Planner, затем общий обработчик использует оба результата. Сотрудники не выполняют предметную операцию вместо PlannerService; они подготавливают входы, от которых зависит следующий шаг.`}),(0,y.jsxs)(p,{caption:`Два входа, один read-only provider и прежний GET`,orientation:`vertical`,children:[(0,y.jsxs)(d,{label:`Ветвь параметров запроса`,children:[(0,y.jsx)(l,{title:`Query GET /tasks`,children:(0,y.jsx)(`p`,{children:`is_done, sort_desc, limit`})}),(0,y.jsx)(u,{label:`FastAPI передаёт значения`}),(0,y.jsx)(l,{title:`get_selection`}),(0,y.jsx)(u,{label:`возвращает`}),(0,y.jsx)(l,{title:`SelectionParams`})]}),(0,y.jsxs)(d,{label:`Ветвь готового сервиса`,children:[(0,y.jsx)(l,{title:`Приложение`,children:(0,y.jsx)(`p`,{children:`уже созданный Planner`})}),(0,y.jsx)(u,{label:`get_planner возвращает`}),(0,y.jsx)(l,{title:`PlannerDep`})]}),(0,y.jsxs)(d,{label:`Общий путь после подготовки`,children:[(0,y.jsx)(l,{title:`SelectionParams + PlannerDep`,children:(0,y.jsx)(`p`,{children:`оба значения доступны одному provider`})}),(0,y.jsx)(u,{label:`входы для`}),(0,y.jsx)(l,{title:`get_selected_tasks`}),(0,y.jsx)(u,{label:`вызывает`}),(0,y.jsx)(l,{title:`PlannerService.select_tasks`}),(0,y.jsx)(u,{label:`список идёт в`}),(0,y.jsx)(l,{title:`GET handler`})]})]}),(0,y.jsx)(`p`,{children:`Первые две дорожки показывают независимые источники, третья объединяет результаты в одном узле. Схема не задаёт порядок ветвей: handler получает оба результата и не запускает повторную выборку.`}),(0,y.jsx)(s,{question:`Что передаём в Depends, чтобы FastAPI подготовил значение?`,options:[`функцию-provider`,`готовый результат вызова функции`,`новую Task для каждого параметра`],correctIndex:0,explanation:`FastAPI получает результат provider на запросе. Ручной вызов при объявлении графа передал бы не ту границу.`})]}),(0,y.jsxs)(o,{number:`04`,title:`Один запрос не равен глобальному кэшу`,children:[(0,y.jsx)(a,{children:`Одинаковая зависимость может понадобиться нескольким узлам одного запроса. FastAPI обычно переиспользует её результат внутри этого запроса, поэтому общий Planner не нужно создавать повторно для каждого параметра.`}),(0,y.jsx)(`p`,{children:`Здесь полезно разделить три вещи: функцию-provider, возвращённый объект и время его использования. FastAPI строит граф для запроса, получает необходимые результаты и может использовать повторный результат той же зависимости в пределах этого запроса. Новый HTTP-запрос начинает новую обработку. Это не functools.lru_cache, не вечный singleton и не обещание одного вызова на все следующие запросы.`}),(0,y.jsx)(`p`,{children:`Singleton здесь означает один общий экземпляр приложения, который переживает несколько запросов. Кэширование зависимости FastAPI такого срока не задаёт: оно повторно использует результат внутри запроса. functools.lru_cache отдельно хранит результаты функции между вызовами по её аргументам; в этом проекте такой механизм не включаем.`}),(0,y.jsx)(`p`,{children:`Можно представить одну карту помещения, которую на время одной экскурсии используют два гида. Они обращаются к одному подготовленному экземпляру карты, но следующая экскурсия не обязана использовать ту же карту. Сравнение помогает понять границу запроса; реальное поведение всё равно определяется графом FastAPI, а не устройством экскурсии.`}),(0,y.jsx)(`p`,{children:`Чтобы увидеть повторное использование, соберём отдельный граф с двумя потребителями и счётчиком. Это эксперимент на один запрос, без новых Planner-маршрутов и производственного счётчика.`}),(0,y.jsx)(h,{question:`Почему результат get_planner нельзя считать одним глобальным экземпляром для всех запросов?`,hint:`Сначала назовём границу, внутри которой FastAPI переиспользует зависимость.`,answer:(0,y.jsx)(`p`,{children:`Переиспользование по умолчанию ограничено обработкой одного запроса. Новый запрос получает свой цикл разрешения графа; это не глобальное хранилище и не lru_cache.`})})]}),(0,y.jsxs)(o,{number:`05`,title:`Override подменяет функцию, а не её результат`,children:[(0,y.jsx)(a,{children:`API-проверке нужен отдельный Planner и собственный JSON-файл. FastAPI позволяет временно заменить provider, не меняя production-код обработчика и не читая рабочие задачи.`}),(0,y.jsx)(`p`,{children:`Override - это тестовая подмена зависимости. В app.dependency_overrides ключом служит исходная функция-provider, которую FastAPI увидел в графе. Значением служит другая функция-provider. FastAPI вызывает замену и использует её результат в тестовом запросе. Если вместо функции положить готовый Planner, FastAPI не получит ожидаемую вызываемую границу.`}),(0,y.jsx)(`p`,{children:`Прежняя API-fixture подменяла app.state.planner, чтобы обычный get_planner вернул тестовый сервис. Теперь мы проверяем саму границу графа: заменяем исходный get_planner в dependency_overrides. Так в запросе меняется provider, а привычный PlannerService и его операции остаются прежними.`}),(0,y.jsx)(`p`,{children:`Представим переключатель источника времени в небольшой проверке расписания. Обычное приложение берёт настоящее время, а тест задаёт фиксированное. Ключ переключателя указывает на исходный provider, значение - на заменяющую функцию. Сервис расписания и его правила при этом не переписываются. Так же override позволяет оставить настоящий GET и заменить только источник Planner.`}),(0,y.jsx)(v,{caption:`независимый фрагмент подмены provider`,code:[`previous = app.dependency_overrides.copy()`,`app.dependency_overrides[get_clock] = fixed_clock`,`try:`,`    response = client.get("/schedule")`,`finally:`,`    app.dependency_overrides.clear()`,`    app.dependency_overrides.update(previous)`].join(`
`)}),(0,y.jsx)(`p`,{children:`Снимите прежний словарь overrides и восстановите его в finally: так очистка не удалит чужие подмены и сработает при ошибке. Тестовый provider возвращает Planner из build_service с JsonStorage в tmp_path. app.state.planner и рабочий data/tasks.json остаются нетронутыми.`}),(0,y.jsx)(`p`,{children:`Следующий поиск ошибки проверяет различие функции и готового объекта. Здесь показан независимый пример с часами, а не готовая настройка Planner.`}),(0,y.jsx)(t,{code:[`app.dependency_overrides[get_clock] = fixed_time`,`response = client.get("/schedule")`].join(`
`),question:`Что не так с этой записью, если fixed_time уже является datetime?`,options:[`В значение карты попал объект, а нужен вызываемый provider`,`Ключом должен быть результат get_clock()`,`Overrides нельзя использовать вместе с TestClient`],correctIndex:0,explanation:`FastAPI вызывает функцию-замену. Объект datetime не подменяет provider; исходная функция остаётся ключом.`,fix:`app.dependency_overrides[get_clock] = fixed_clock`})]}),(0,y.jsxs)(o,{number:`06`,title:`Сравниваем контракт и границы отказа`,children:[(0,y.jsx)(a,{children:`Успешный ответ на тестовых данных сам по себе не подтверждает изоляцию. Мы сопоставим знакомую выборку, состояние JSON и восстановление обычного provider.`}),(0,y.jsx)(`p`,{children:`Сначала сравним GET без query: должны сохраниться тот же default limit и тот же порядок ответа. Затем проверим is_done, оба направления sort_desc, limit на границах и ошибочные значения за ними. Query-ошибка по-прежнему отклоняется до выполнения выборки. SelectionParams не отменяет валидацию FastAPI и не заменяет ограничение сервиса там, где оно уже предусмотрено.`}),(0,y.jsx)(`p`,{children:`Для доказательства изоляции тест создаёт задачи через временный сервис, получает из GET только этот набор и после запроса сравнивает его состояние. Рабочий JSON не используется для подготовки или очистки данных. В конце мы удаляем override и повторно проверяем, что штатный get_planner снова доступен. Это отдельная проверка состояния приложения, а не вывод из того, что ответ теста выглядел правильным.`}),(0,y.jsx)(`p`,{children:`Если временный provider намеренно сообщает о недоступности, API не должен возвращать ложный успешный список или менять задачи. Для такого контролируемого отказа подходит HTTP 503, то есть сервис запроса временно недоступен. Это не 403: речь не о правах клиента. После отказа прежний override также нужно восстановить.`}),(0,y.jsx)(`p`,{children:`Наконец, проверим неизменность операций, которые меняют задачи. POST, PUT, PATCH и DELETE продолжают идти через тот же PlannerService, а GET использует только select_tasks. Мы не переносим CRUD в зависимости и не добавляем второй репозиторий или второе хранилище для приложения.`}),(0,y.jsx)(f,{prompt:`Соединим проверку с тем, что она действительно подтверждает.`,leftTitle:`Проверка`,rightTitle:`Что подтверждено`,pairs:[{left:`GET с отдельным сервисом`,right:`Ответ пришёл из тестового набора`},{left:`Проверка tmp_path JSON`,right:`Рабочий файл не используется`},{left:`Снимок overrides до и после`,right:`Состояние приложения восстановлено`},{left:`Проверки POST и PATCH`,right:`Изменяющие операции сохранили старый путь`}],explanation:`Каждая проверка отвечает на отдельный вопрос. Один корректный JSON-ответ не доказывает восстановление provider.`})]}),(0,y.jsxs)(o,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(a,{children:`Мы меняем только подготовку уже существующей GET-выборки и тестовую точку подмены. Предметный Planner, его JSON-хранилище и публичный HTTP-договор остаются нашей опорой.`}),(0,y.jsx)(c,{variant:`connected`,items:[{title:`Соберём входы`,description:`Вынесем is_done, sort_desc и limit в SelectionParams и get_selection без изменения defaults и ограничений.`},{title:`Соединим граф`,description:`Подадим прежний Planner и подготовленные параметры в read-only get_selected_tasks, сохранив select_tasks источником выборки.`},{title:`Изолируем запрос`,description:`Подменим get_planner provider на сервис с JsonStorage во временном каталоге и восстановим прежние overrides после проверки.`},{title:`Подтвердим старое поведение`,description:`Сравним GET, фильтры и limit, проверим контролируемый отказ, состояние данных и прежние изменяющие операции.`}]}),(0,y.jsx)(`p`,{children:`Маршрут идёт от контейнера параметров к графу, затем к управляемой тестовой границе. До первого запроса мы подготовим отдельные данные; после него сверим не только ответ, но и JSON, зависимости и прежний контракт. Небольшой эксперимент со счётчиком можно выполнить отдельно, не добавляя его в само приложение.`}),(0,y.jsx)(`p`,{children:`Итогом будет один понятный GET-путь поверх того же Planner, без новых предметных операций. Следующий материал сможет опереться на читаемый граф и изолированную fixture, чтобы изучать Headers и Response на настоящем ресурсе.`})]}),(0,y.jsx)(o,{number:`08`,title:`Коротко зафиксируем границы`,children:(0,y.jsx)(n,{points:[(0,y.jsx)(y.Fragment,{children:`SelectionParams объединяет query-значения и не становится Task.`}),(0,y.jsx)(y.Fragment,{children:`get_selection подготавливает параметры; select_tasks остаётся операцией PlannerService.`}),(0,y.jsx)(y.Fragment,{children:`get_selected_tasks получает сервис и параметры как два результата графа.`}),(0,y.jsx)(y.Fragment,{children:`FastAPI может использовать результат одной зависимости внутри запроса, но не создаёт глобальный кэш.`}),(0,y.jsx)(y.Fragment,{children:`Overrides связывают исходный provider с заменяющей функцией.`}),(0,y.jsx)(y.Fragment,{children:`Временный сервис и JSON изолируют проверку от рабочего файла.`}),(0,y.jsx)(y.Fragment,{children:`HTTP-контракт и пути CRUD продолжают работать как прежде.`})]})})]})}export{x as Lesson64};